-- Multas: pendentes apenas para um grupo de alunos; as demais foram pagas
UPDATE multa
   SET status = 'paga',
       data_pagamento = min(date(data_geracao, '+' || ((id_multa % 6) + 1) || ' days'), date('now'))
 WHERE id_emprestimo NOT IN (283, 377, 468, 644, 662, 776, 855, 1175, 1232, 1334, 1353, 1364, 1507, 1661, 1664, 1683, 1834, 1985, 2207, 2225, 2290, 2433, 2507, 2513, 2526, 2583);

